/* V312 — Boavista 11 ene 2015 final hardfix. Foto embebida, sin depender del asset roto. */
(()=>{
'use strict';

const PHOTO='data:image/webp;base64,';
const norm=s=>String(s||'')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g,'')
  .toLowerCase()
  .replace(/\s+/g,' ')
  .trim();

function isTarget(card){
  const h=norm(card.querySelector('h3,h4')?.textContent||'');
  const all=norm(card.textContent||'');
  return h.includes('boavista') && all.includes('11 ene 2015');
}

function paint(card){
  if(!card?.isConnected || !isTarget(card)) return;

  card.querySelectorAll(
    '.v120-exact-event-bg,.v35-history-bg-photo,.v35-champion-bg-photo,.v286-boavista-2015-bg,.v295-boavista-data-bg,.v310-boavista-bg'
  ).forEach(n=>n.remove());
  card.querySelectorAll(':scope > .v295-boavista-data-shade,:scope > .v286-boavista-2015-shade,:scope > .v310-boavista-shade').forEach(n=>n.remove());

  const img=document.createElement('img');
  img.className='v35-history-bg-photo v120-exact-event-bg v120-photo-only-bg v310-boavista-bg';
  img.alt='Boavista · Campeón · Primera Fuerza · 11 ene 2015';
  img.src=PHOTO;
  img.loading='eager';
  img.decoding='sync';
  img.style.cssText='position:absolute!important;inset:0!important;width:100%!important;height:100%!important;display:block!important;visibility:visible!important;opacity:1!important;z-index:0!important;object-fit:cover!important;object-position:center 43%!important;transform:none!important;filter:none!important;margin:0!important;padding:0!important;border:0!important;pointer-events:none!important;';
  card.prepend(img);

  const shade=document.createElement('span');
  shade.className='v310-boavista-shade';
  shade.setAttribute('aria-hidden','true');
  shade.style.cssText='position:absolute!important;inset:0!important;z-index:1!important;pointer-events:none!important;background:linear-gradient(180deg,rgba(2,5,45,.04) 0%,rgba(2,5,45,.08) 36%,rgba(2,5,45,.24) 66%,rgba(2,5,45,.64) 100%),linear-gradient(90deg,rgba(2,5,45,.12),rgba(2,5,45,.01) 72%)!important;';
  card.insertBefore(shade,img.nextSibling);

  card.style.setProperty('position','relative','important');
  card.style.setProperty('overflow','hidden','important');
  card.style.setProperty('isolation','isolate','important');
  card.style.setProperty('background-color','#060653','important');
  card.style.setProperty('background-image','linear-gradient(180deg,rgba(2,5,45,.04) 0%,rgba(2,5,45,.08) 36%,rgba(2,5,45,.24) 66%,rgba(2,5,45,.64) 100%),url("'+PHOTO+'")','important');
  card.style.setProperty('background-size','cover','important');
  card.style.setProperty('background-position','center 43%','important');
  card.style.setProperty('background-repeat','no-repeat','important');

  card.querySelectorAll('.v35-history-moment-shade,.v120-exact-shade').forEach(n=>{
    n.style.setProperty('display','none','important');
  });

  card.querySelectorAll('.v35-history-moment-content,.v35-champion-content,.v115-card-body').forEach(n=>{
    n.style.setProperty('position','relative','important');
    n.style.setProperty('z-index','2','important');
    n.style.setProperty('background','transparent','important');
  });

  card.querySelectorAll('.v35-history-status span,.v35-history-fact,.v35-champion-fact').forEach(n=>{
    n.style.setProperty('position','relative','important');
    n.style.setProperty('z-index','3','important');
    n.style.setProperty('background','rgba(3,8,70,.34)','important');
  });

  card.classList.add('v35-history-moment-photo','v120-has-exact-bg','v120-photo-only-card');
  card.dataset.v310Boavista='ready';
}

function patch(){
  if(!/history|safe-about/.test(location.hash||'')) return;
  document.querySelectorAll('.v35-history-moment,.v35-champion-card,.v115-card').forEach(card=>{
    if(isTarget(card)) paint(card);
  });
}

let raf=0;
function schedule(ms=0){
  clearTimeout(schedule.t);
  schedule.t=setTimeout(()=>{
    cancelAnimationFrame(raf);
    raf=requestAnimationFrame(patch);
  },ms);
}

window.addEventListener('hashchange',()=>schedule(40));
document.addEventListener('click',e=>{
  if(e.target.closest('[data-v35-tab],button,[data-route]')) schedule(80);
},true);

new MutationObserver(ms=>{
  const relevant=ms.some(m=>[...m.addedNodes].some(n=>
    n.nodeType===1 &&
    !n.classList?.contains('v310-boavista-bg') &&
    !n.classList?.contains('v310-boavista-shade')
  ));
  if(relevant) schedule(30);
}).observe(document.querySelector('#screen')||document.body,{childList:true,subtree:true});

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',()=>schedule(60),{once:true});
}else{
  schedule(20);
}
setTimeout(patch,300);
setTimeout(patch,900);
setTimeout(patch,1800);
})();